import{_ as a,o as l,c as h,a3 as e}from"./chunks/framework.Q4yG9rk_.js";const d=JSON.parse('{"title":"礼记","description":"儒家五经之一：礼制的义理与生活细节，四十九篇，《大学》《中庸》即出其中。","frontmatter":{"title":"礼记","description":"儒家五经之一：礼制的义理与生活细节，四十九篇，《大学》《中庸》即出其中。","category":"guide","aliases":["礼记","小戴礼记","liji","礼记篇章","礼记目录"],"source":["《礼记》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/liji/index.md","filePath":"lizhimingde/sishu-wujing/liji/index.md","lastUpdated":1789987057000}'),n={name:"lizhimingde/sishu-wujing/liji/index.md"};function r(s,i,g,u,o,t){return l(),h("div",null,[...i[0]||(i[0]=[e('<h1 id="礼记" tabindex="-1">礼记 <a class="header-anchor" href="#礼记" aria-label="Permalink to &quot;礼记&quot;">​</a></h1><p>《礼记》是「三礼」（《仪礼》《周礼》《礼记》）之一，由汉儒戴圣编定（故又称《小戴礼记》），四十九篇。它不是礼制的条文，而是<strong>对礼的解释、讨论与发挥</strong>——一部关于「为什么这样行礼」的文集。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><ul><li><strong>性质</strong>：《仪礼》记「怎么做」，《礼记》说明「为什么」。所以它更近于礼学的义理与哲学。</li><li><strong>内容跨度极大</strong>：有制度（王制、月令）、有礼节（曲礼、少仪、内则）、有丧祭专论（檀弓、丧服小记、祭义）、有教育（学记）、有音乐（乐记）、有政治哲学（礼运）、有心性之学（大学、中庸）。</li><li><strong>四书中的两部出在这里</strong>：《大学》是第四十二篇，《中庸》是第三十一篇——朱熹把它们抽出来独立成书。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>「礼」的义理在这一部里说透了</strong>：礼不是繁文缛节，而是「自卑而尊人」的社会语法；「礼也者，理之不可易者也」。</li><li><strong>《礼运》给了一个理想社会图景</strong>：「大道之行也，天下为公」——大同与小康之说，影响深远。</li><li><strong>《学记》是中国最早的教育学专论</strong>：「教学相长」「藏焉修焉，息焉游焉」皆出此。</li><li><strong>《乐记》是中国音乐美学的主干文献</strong>：「乐者，天地之和也」。</li><li><strong>《檀弓》记孔门丧礼与言行</strong>，是《论语》之外最重要的孔门材料。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li><strong>先读《学记》《礼运》《乐记》三篇</strong>——一篇教育、一篇政治理想、一篇艺术论，最能见《礼记》的思想面貌；</li><li><strong>再读《大学》《中庸》</strong>（本栏目已独立成篇），知道它们在《礼记》中的位置；</li><li><strong>《曲礼》《少仪》《内则》</strong> 看日常生活的礼——饮食、应对、进退的细密规矩；</li><li><strong>《檀弓》</strong> 读故事：孔门丧礼中的言行，文字极好；</li><li><strong>注本</strong>：可参考孙希旦《礼记集解》、王梦鸥《礼记今注今译》。</li></ol><h2 id="篇章" tabindex="-1">篇章 <a class="header-anchor" href="#篇章" aria-label="Permalink to &quot;篇章&quot;">​</a></h2><p>一篇一页，共 <strong>49 页</strong>。</p><ol><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-01">曲礼上</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-02">曲礼下</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-03">檀弓上</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-04">檀弓下</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-05">王制</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-06">月令</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-07">曾子问</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-08">文王世子</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-09">礼运</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-10">礼器</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-11">郊特牲</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-12">内则</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-13">玉藻</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-14">明堂位</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-15">丧服小记</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-16">大传</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-17">少仪</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-18">学记</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-19">乐记</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-20">杂记上</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-21">杂记下</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-22">丧大记</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-23">祭法</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-24">祭义</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-25">祭统</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-26">经解</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-27">哀公问</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-28">仲尼燕居</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-29">孔子闲居</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-30">坊记</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-31">中庸</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-32">表记</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-33">缁衣</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-34">奔丧</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-35">问丧</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-36">服问</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-37">间传</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-38">三年问</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-39">深衣</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-40">投壶</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-41">儒行</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-42">大学</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-43">冠义</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-44">昏义</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-45">乡饮酒义</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-46">射义</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-47">燕义</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-48">聘义</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/liji/chapter-49">丧服四制</a></li></ol><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li>各章页当前为骨架（篇名、位置、待整理标记），<strong>原文转录、字词释义与逐章解读后续分批推进</strong>。</li><li>整理方式与《道德经》一致：<strong>一章一页</strong>，目录与文件一一对应。</li><li>参考：孙希旦《礼记集解》、王梦鸥《礼记今注今译》</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>本栏目已独立成篇者：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a>（皆原出《礼记》）</li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/shijing/">诗经</a> · <a href="/Dao/lizhimingde/sishu-wujing/shangshu/">尚书</a> · <a href="/Dao/lizhimingde/sishu-wujing/chunqiu/">春秋</a> · <a href="/Dao/lizhimingde/sishu-wujing/yijing">周易</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',15)])])}const c=a(n,[["render",r]]);export{d as __pageData,c as default};
